<?php
namespace App\Controllers;

use App\Core\{Auth,Authorization,CSRF,Database,TenantContext,View,Audit,HttpException};
use App\Services\{ModuleService,CommissionService,LoyaltyService,NotificationService};

final class SalesController
{
    private function enabled():void{ModuleService::require('products');}

    public function products():void
    {
        $this->enabled();Authorization::require('products.view');$t=TenantContext::id();$q=Database::connection()->prepare('SELECT * FROM products WHERE tenant_id=:t ORDER BY active DESC,name');$q->execute(['t'=>$t]);View::render('sales/products',['title'=>'Produtos','products'=>$q->fetchAll(),'stockEnabled'=>ModuleService::has('stock',$t)]);
    }

    public function storeProduct():void
    {
        $this->enabled();Authorization::require('products.create');CSRF::enforce();$t=TenantContext::id();$d=$this->productData($t);$pdo=Database::connection();$q=$pdo->prepare('INSERT INTO products(tenant_id,name,sku,category,description,cost_price,sale_price,stock,minimum_stock,unit,commission_type,commission_value,active,created_at,updated_at)VALUES(:t,:name,:sku,:category,:description,:cost,:price,:stock,:minimum,:unit,:commission_type,:commission_value,1,NOW(),NOW())');$q->execute(['t'=>$t]+$d);$id=(int)$pdo->lastInsertId();Audit::log('PRODUCT_CREATED','products',$id,null,['name'=>$d['name']]);header('Location: /products/'.$id.'/edit');exit;
    }

    public function editProduct(string $id):void
    {
        $this->enabled();Authorization::require('products.edit');$t=TenantContext::id();$q=Database::connection()->prepare('SELECT * FROM products WHERE id=:id AND tenant_id=:t');$q->execute(['id'=>(int)$id,'t'=>$t]);$product=$q->fetch();if(!$product)HttpException::abort(404,'Produto não encontrado.');View::render('sales/product-form',['title'=>'Editar produto','product'=>$product,'stockEnabled'=>ModuleService::has('stock',$t)]);
    }

    public function updateProduct(string $id):void
    {
        $this->enabled();Authorization::require('products.edit');CSRF::enforce();$t=TenantContext::id();$pid=(int)$id;$pdo=Database::connection();$q=$pdo->prepare('SELECT * FROM products WHERE id=:id AND tenant_id=:t');$q->execute(['id'=>$pid,'t'=>$t]);$old=$q->fetch();if(!$old)HttpException::abort(404,'Produto não encontrado.');$d=$this->productData($t,$old);$active=isset($_POST['active'])?1:0;$sql='UPDATE products SET name=:name,sku=:sku,category=:category,description=:description,cost_price=:cost,sale_price=:price,minimum_stock=:minimum,unit=:unit,commission_type=:commission_type,commission_value=:commission_value,active=:active,updated_at=NOW()';$params=$d+['active'=>$active,'id'=>$pid,'t'=>$t];if(ModuleService::has('stock',$t))$sql.=',stock=:stock';else unset($params['stock']);$sql.=' WHERE id=:id AND tenant_id=:t';$pdo->prepare($sql)->execute($params);Audit::log('PRODUCT_UPDATED','products',$pid,$old,['name'=>$d['name'],'active'=>$active]);header('Location: /products/'.$pid.'/edit');exit;
    }

    public function deactivateProduct(string $id):void
    {
        $this->enabled();Authorization::require('products.edit');CSRF::enforce();$q=Database::connection()->prepare('UPDATE products SET active=0,updated_at=NOW() WHERE id=:id AND tenant_id=:t');$q->execute(['id'=>(int)$id,'t'=>TenantContext::id()]);if(!$q->rowCount())HttpException::abort(404,'Produto não encontrado.');Audit::log('PRODUCT_DEACTIVATED','products',(int)$id);header('Location: /products');exit;
    }

    public function index():void
    {
        $this->enabled();Authorization::require('sales.view');$t=TenantContext::id();$pdo=Database::connection();$prof=$this->professionalId($pdo,$t);$q=$pdo->prepare('SELECT s.*,p.name professional_name,c.name customer_name FROM sales s LEFT JOIN professionals p ON p.id=s.professional_id AND p.tenant_id=s.tenant_id LEFT JOIN customers c ON c.id=s.customer_id AND c.tenant_id=s.tenant_id WHERE s.tenant_id=:t AND (:prof IS NULL OR s.professional_id=:prof2) ORDER BY s.id DESC LIMIT 150');$q->execute(['t'=>$t,'prof'=>$prof,'prof2'=>$prof]);$products=$pdo->prepare('SELECT id,name,sale_price,stock FROM products WHERE tenant_id=:t AND active=1 ORDER BY name');$products->execute(['t'=>$t]);$customers=$pdo->prepare("SELECT id,name FROM customers WHERE tenant_id=:t AND status='active' ORDER BY name LIMIT 500");$customers->execute(['t'=>$t]);View::render('sales/index',['title'=>'PDV e vendas','sales'=>$q->fetchAll(),'products'=>$products->fetchAll(),'customers'=>$customers->fetchAll(),'stockEnabled'=>ModuleService::has('stock',$t),'professional'=>$prof]);
    }

    public function store():void
    {
        $this->enabled();Authorization::require('sales.create');CSRF::enforce();$t=TenantContext::id();$pid=filter_var($_POST['product_id']??null,FILTER_VALIDATE_INT);$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_FLOAT);$customerId=filter_var($_POST['customer_id']??null,FILTER_VALIDATE_INT)?:null;if(!$pid||$qty===false||$qty<=0)HttpException::abort(422,'Item inválido.');$pdo=Database::connection();$stockEnabled=ModuleService::has('stock',$t);$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM products WHERE id=:id AND tenant_id=:t AND active=1 FOR UPDATE');$q->execute(['id'=>$pid,'t'=>$t]);$p=$q->fetch();if(!$p)throw new \DomainException('Produto indisponível.');if($stockEnabled&&(float)$p['stock']<$qty)throw new \DomainException('Estoque insuficiente.');if($customerId){$c=$pdo->prepare("SELECT 1 FROM customers WHERE id=:id AND tenant_id=:t AND status='active'");$c->execute(['id'=>$customerId,'t'=>$t]);if(!$c->fetchColumn())throw new \DomainException('Cliente inválido.');}$subtotal=round((float)$p['sale_price']*$qty,2);$discount=(float)($_POST['discount']??0);if($discount>0&&!Authorization::allows('sales.discount'))throw new \DomainException('Desconto não autorizado.');$discount=max(0,min($discount,$subtotal));$prof=$this->professionalId($pdo,$t);$method=(string)($_POST['payment_method']??'pix');if(!in_array($method,['pix','dinheiro','credito','debito','outro'],true))$method='outro';$pdo->prepare("INSERT INTO sales(tenant_id,professional_id,customer_id,user_id,subtotal,discount,total,payment_method,status,created_at)VALUES(:t,:p,:c,:u,:sub,:d,:total,:method,'completed',NOW())")->execute(['t'=>$t,'p'=>$prof,'c'=>$customerId,'u'=>Auth::user()['id'],'sub'=>$subtotal,'d'=>$discount,'total'=>$subtotal-$discount,'method'=>$method]);$sale=(int)$pdo->lastInsertId();$commissionSnapshot=0.0;if(($p['commission_type']??'none')==='percent')$commissionSnapshot=round(($subtotal-$discount)*(float)$p['commission_value']/100,2);elseif(($p['commission_type']??'none')==='fixed')$commissionSnapshot=round((float)$p['commission_value']*$qty,2);$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,quantity,unit_price,discount,total,cost_snapshot,commission_amount_snapshot)VALUES(:s,:p,:q,:price,:d,:total,:cost,:commission)')->execute(['s'=>$sale,'p'=>$pid,'q'=>$qty,'price'=>$p['sale_price'],'d'=>$discount,'total'=>$subtotal-$discount,'cost'=>$p['cost_price'],'commission'=>$commissionSnapshot]);if($stockEnabled){$balance=(float)$p['stock']-$qty;$pdo->prepare('UPDATE products SET stock=:stock,updated_at=NOW() WHERE id=:id AND tenant_id=:t')->execute(['stock'=>$balance,'id'=>$pid,'t'=>$t]);$pdo->prepare("INSERT INTO product_stock_movements(tenant_id,product_id,sale_id,type,quantity,balance_after,user_id,created_at)VALUES(:t,:p,:s,'sale',:q,:b,:u,NOW())")->execute(['t'=>$t,'p'=>$pid,'s'=>$sale,'q'=>-$qty,'b'=>$balance,'u'=>Auth::user()['id']]);}$pdo->commit();Audit::log('SALE_CREATED','sales',$sale);CommissionService::product($t,$sale);if($customerId)LoyaltyService::earn($t,$customerId,$subtotal-$discount,'sale',$sale);if(ModuleService::has('finance',$t)){$pdo->prepare("INSERT IGNORE INTO financial_transactions(tenant_id,source_type,source_id,type,description,amount,payment_method,status,idempotency_key,competence_at,paid_at,created_at,updated_at)VALUES(:t,'sale',:sid,'income','Venda de produtos',:amount,:method,'paid',:key,CURDATE(),NOW(),NOW(),NOW())")->execute(['t'=>$t,'sid'=>$sale,'amount'=>$subtotal-$discount,'method'=>$method,'key'=>'sale-'.$sale]);}if($stockEnabled&&$balance<=(float)$p['minimum_stock'])NotificationService::tenantOwners($t,'stock.low','Estoque baixo',$p['name'].' chegou a '.number_format($balance,3,',','.').' '.$p['unit'],'/stock','warning');}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();HttpException::abort(422,$e->getMessage());}header('Location: /sales');exit;
    }

    public function cancel(string $id):void
    {
        $this->enabled();Authorization::require('sales.cancel');CSRF::enforce();$t=TenantContext::id();$saleId=(int)$id;$reason=trim((string)($_POST['reason']??''));if(strlen($reason)<3)HttpException::abort(422,'Informe o motivo do cancelamento.');$pdo=Database::connection();$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT * FROM sales WHERE id=:id AND tenant_id=:t FOR UPDATE");$q->execute(['id'=>$saleId,'t'=>$t]);$sale=$q->fetch();if(!$sale)throw new \DomainException('Venda não encontrada.');if($sale['status']==='cancelled')throw new \DomainException('Venda já cancelada.');if(ModuleService::has('stock',$t)){$items=$pdo->prepare('SELECT * FROM sale_items WHERE sale_id=:s');$items->execute(['s'=>$saleId]);foreach($items->fetchAll() as $item){$p=$pdo->prepare('SELECT stock FROM products WHERE id=:p AND tenant_id=:t FOR UPDATE');$p->execute(['p'=>$item['product_id'],'t'=>$t]);$stock=$p->fetchColumn();if($stock===false)continue;$balance=(float)$stock+(float)$item['quantity'];$pdo->prepare('UPDATE products SET stock=:b,updated_at=NOW() WHERE id=:p AND tenant_id=:t')->execute(['b'=>$balance,'p'=>$item['product_id'],'t'=>$t]);$pdo->prepare("INSERT INTO product_stock_movements(tenant_id,product_id,sale_id,type,quantity,balance_after,user_id,reason,created_at)VALUES(:t,:p,:s,'sale_reversal',:q,:b,:u,:r,NOW())")->execute(['t'=>$t,'p'=>$item['product_id'],'s'=>$saleId,'q'=>$item['quantity'],'b'=>$balance,'u'=>Auth::user()['id'],'r'=>$reason]);}}$pdo->prepare("UPDATE sales SET status='cancelled',cancel_reason=:r,cancelled_by=:u,cancelled_at=NOW() WHERE id=:id AND tenant_id=:t")->execute(['r'=>$reason,'u'=>Auth::user()['id'],'id'=>$saleId,'t'=>$t]);$pdo->commit();Audit::log('SALE_CANCELLED','sales',$saleId,$sale,['reason'=>$reason]);CommissionService::reverse('product',$t,$saleId);if(!empty($sale['customer_id']))LoyaltyService::reverse($t,(int)$sale['customer_id'],'sale',$saleId);if(ModuleService::has('finance',$t))$pdo->prepare("UPDATE financial_transactions SET status='cancelled',updated_at=NOW() WHERE tenant_id=:t AND source_type='sale' AND source_id=:sid")->execute(['t'=>$t,'sid'=>$saleId]);}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();HttpException::abort(422,$e->getMessage());}header('Location: /sales');exit;
    }

    private function productData(int $t,?array $old=null):array
    {
        $name=trim((string)($_POST['name']??''));$sku=trim((string)($_POST['sku']??''));$category=trim((string)($_POST['category']??''));$description=trim((string)($_POST['description']??''));$price=filter_var(str_replace(',','.',(string)($_POST['sale_price']??'')),FILTER_VALIDATE_FLOAT);$cost=filter_var(str_replace(',','.',(string)($_POST['cost_price']??'0')),FILTER_VALIDATE_FLOAT);if(strlen($name)<2||$price===false||$price<0||$cost===false||$cost<0)HttpException::abort(422,'Produto inválido.');$stockEnabled=ModuleService::has('stock',$t);$stock=$stockEnabled?filter_var(str_replace(',','.',(string)($_POST['stock']??($old['stock']??0))),FILTER_VALIDATE_FLOAT):(float)($old['stock']??0);$minimum=$stockEnabled?filter_var(str_replace(',','.',(string)($_POST['minimum_stock']??($old['minimum_stock']??0))),FILTER_VALIDATE_FLOAT):0;if($stock===false||$stock<0||$minimum===false||$minimum<0)HttpException::abort(422,'Estoque inválido.');$ct=(string)($_POST['commission_type']??'none');if(!in_array($ct,['none','percent','fixed'],true))$ct='none';$cv=filter_var(str_replace(',','.',(string)($_POST['commission_value']??'0')),FILTER_VALIDATE_FLOAT);if($cv===false||$cv<0||($ct==='percent'&&$cv>100))HttpException::abort(422,'Comissão do produto inválida.');return ['name'=>$name,'sku'=>$sku?:null,'category'=>$category?:null,'description'=>$description?:null,'cost'=>$cost,'price'=>$price,'stock'=>$stock,'minimum'=>$minimum,'unit'=>trim((string)($_POST['unit']??'un'))?:'un','commission_type'=>$ct,'commission_value'=>$cv];
    }

    private function professionalId(\PDO $pdo,int $t):?int{if((Auth::user()['role']??'')!=='professional')return null;$q=$pdo->prepare('SELECT id FROM professionals WHERE tenant_id=:t AND user_id=:u AND active=1');$q->execute(['t'=>$t,'u'=>Auth::user()['id']]);$id=$q->fetchColumn();if(!$id)HttpException::abort(403,'Seu usuário não está vinculado a um profissional ativo.');return (int)$id;}
}
